const FREQ_RANK = new Map();

for (const [i, w] of FREQ_BLOB.split(' ').entries()) {
  if (!FREQ_RANK.has(w)) {
    FREQ_RANK.set(w, i);
  }
}

/**
 * The locale the APP is running in, taken from the environment.
 *
 * The composer used to be asked for its own `lang` and never had one: the
 * editor element carries no `lang` attribute at all, so that read was always
 * `''` and the fallback under it did all the work. The app's i18n provider
 * writes the locale it is running in to `<html lang>` on every change
 * (`applyDocumentLocale` -> `document.documentElement.lang`), so the document
 * element is the real answer, and `navigator.language` is the last resort
 * after it.
 *
 * `''` when neither is available, so a caller can tell "no locale anywhere"
 * from a resolved one; activeLocale() is the one place that needs a hard
 * default, and it says 'en' explicitly.
 */
function documentLocale() {
  return document.documentElement.lang || navigator.language || '';
}

/** The locale the editor should actually be checked in. */
function activeLocale(prefs) {
  if (prefs.language && prefs.language !== 'auto') {
    return resolveLocale(prefs.language);
  }

  return resolveLocale(documentLocale() || 'en');
}

/**
 * The locale the Custom Words page ADDS words to.
 *
 * It has to agree with the right-click menu, which writes through
 * activeLocale(): a word added from a German composer belongs in the `de`
 * list. The page used to prefer "whichever locale has the most words", so a
 * word added in the composer could land in a list the page was not showing —
 * invisible there, and impossible to delete from it. The header named the
 * other locale, which made the word recoverable but not obvious.
 *
 * So, in order:
 *   1. an explicitly configured Language wins — that is the dictionary the
 *      user picked, and the menu uses it too;
 *   2. otherwise it uses the SAME resolution activeLocale() uses: the app's
 *      own locale, from `<html lang>` then `navigator.language`. There is no
 *      composer branch any more — the composer element has no `lang` of its
 *      own to read, and this page is normally reached from Settings, where no
 *      composer is mounted;
 *   3. only when the environment offers no locale at all does it fall back to
 *      a locale that HAS words, because an empty list there looks like the
 *      words were lost.
 *
 * The page lists EVERY locale's words (see DictionaryPage), so even that
 * fallback cannot hide a word: no word is ever invisible AND undeletable.
 */
function pageLocale(prefs) {
  if (prefs.language && prefs.language !== 'auto') {
    return resolveLocale(prefs.language);
  }

  const environment = documentLocale();

  if (environment) {
    return resolveLocale(environment);
  }

  // No locale anywhere: whichever locale actually has words beats an empty
  // list.
  let best = null;
  let bestCount = 0;

  for (const [locale, set] of allowed) {
    if (set.size > bestCount) {
      best = locale;
      bestCount = set.size;
    }
  }

  return best || activeLocale(prefs);
}

/** Ensure the active locale is loaded, fetching if needed. */
function ensureLocale(prefs) {
  const locale = activeLocale(prefs);

  if (locale === 'en') {
    return Promise.resolve(rankFor('en'));
  }

  return loadDictionary(locale);
}

/**
 * Turn the composer's spell checker on or off, through the host.
 *
 * The red squiggle is Chromium's, and Chromium only paints it for an element
 * whose `spellcheck` is on — which the app sets to false. `host.composer
 * .setSpellcheck` is the supported way to flip it: the app owns the element
 * and applies the state itself.
 *
 * This used to write `el.spellcheck` and `el.lang` onto the composer elements
 * directly. That reached into the app's own DOM (forbidden by the desktop
 * surface rule), and it lost the fight anyway: the composer's reconciler
 * rewrites the editor on every keystroke, so the attribute went back to false
 * and the squiggles stayed off. There is NO DOM fallback any more — a build
 * without the API simply keeps Chromium's spell check off. Everything else
 * still works: our suggestions are ranked from our own dictionary, and the
 * host's spelling is only the underline.
 *
 * Feature-detected on purpose: `setSpellcheck` is newer than this plugin's
 * floor, so an older shell has to keep loading the plugin.
 */
function applySpellcheck(enabled) {
  const composer = host.composer;
  const setSpellcheck = composer?.setSpellcheck;

  if (typeof setSpellcheck !== 'function') {
    return;
  }

  try {
    const pending = setSpellcheck.call(composer, null, Boolean(enabled));

    // The host crosses to the main process; a refusal must not surface as an
    // unhandled rejection on a toggle the user already saw.
    if (pending && typeof pending.catch === 'function') {
      pending.catch(() => {});
    }
  } catch {

    // Host refused: the underline stays off, the menu still works.
  }
}

// ---------------------------------------------------------------------------
// Dictionary page — /spellcheck-dictionary, with a sidebar tab.
//
// Every custom word ever added from the right-click menu lives here, with
// search, add and delete. It reads the SAME store the menu writes, so an add in
// either place shows up in both immediately.
// ---------------------------------------------------------------------------

function DictionaryPage({ prefs, storage }) {
  const [query, setQuery] = useState('');
  const [draft, setDraft] = useState('');

  // Subscribing to the version atom is what makes the page LIVE: every add or
  // delete bumps it, and this re-renders without a page switch. Without this
  // line the list only updates when you leave and come back.
  useValue($allowedVersion);

  // New words go to the locale the composer is checking in — the same one the
  // right-click menu writes to, so an add here and an add there land in the
  // same list.
  const locale = pageLocale(prefs);

  // The LIST, though, is every word from every locale. Showing only the active
  // locale's words left a word added from another composer language invisible
  // here, and therefore impossible to delete. Each entry carries its own
  // locale, which is what the delete button acts on.
  const entries = [];

  for (const [loc, set] of allowed) {
    for (const word of set) {
      entries.push({ locale: loc, word });
    }
  }

  entries.sort((a, b) => a.word.localeCompare(b.word) || a.locale.localeCompare(b.locale));

  // Named in the header (and on each row when there is more than one), so the
  // page always says which dictionary a word belongs to.
  const locales = [...new Set(entries.map((e) => e.locale))].sort();

  // Search filters as you type. Prefix match on the leading characters, so
  // "o" shows every word starting with o, "op" narrows to op..., "ope" to
  // ope... — and a query that is not a prefix (say "code") still matches
  // anywhere in the word, because that is what people expect from a search
  // box. Matching is case-insensitive.
  const needle = query.trim().toLowerCase();
  const shown = needle ?
  entries.filter((e) => {
    const lower = e.word.toLowerCase();

    return lower.startsWith(needle) || lower.includes(needle);
  }) :
  entries;

  const commit = () => {
    const value = draft.trim();

    if (!value) {
      return;
    }

    // Accept a comma/space separated batch — the same shape the settings
    // page used, which is what people paste in from elsewhere.
    const added = [];
    const existed = [];

    for (const raw of value.split(/[,\s]+/)) {
      if (addCustomWord(locale, raw, storage)) {
        added.push(raw.toLowerCase());
      } else if (raw.trim()) {
        existed.push(raw.toLowerCase());
      }
    }

    if (added.length) {
      notifyHost('success', `Added ${added.length} word${added.length > 1 ? 's' : ''}`);
    } else if (existed.length) {
      notifyHost('info', 'Those words were already in your dictionary');
    }

    // One field, so both states clear together. Leaving the query behind
    // would hide the word that was just added behind a stale filter.
    setDraft('');
    setQuery('');
  };

  // Delete goes through removeCustomWord(), the mirror of the add above, so a
  // removed word leaves BOTH stores — our list and the app's dictionary. The
  // locale is the ROW's, not the active one: the row can belong to a
  // dictionary other than the one the composer is using.
  const remove = (word, wordLocale) => {
    if (removeCustomWord(wordLocale, word, storage)) {
      notifyHost('success', `Removed “${word}”`);
    }
  };

  const total = entries.length;
  const dict = rankFor(locale);


  // Layout mirrors the quota pane exactly. The load-bearing part is
  // boxSizing:border-box on a full-height padded box — without it the
  // padding overflows and the pane can collapse to nothing, which is
  // indistinguishable from a blank page: the component mounts and
  // renders, but nothing is visible.
  return jsxs('div', {
    className: 'flex h-full flex-col gap-3 p-4',
    style: { minHeight: 0, minWidth: 0, overflow: 'auto', boxSizing: 'border-box' },
    children: [
    // --- header: language + counts ------------------------------------
    jsx('div', { className: 'flex items-baseline justify-between', key: 'head', children: [
      jsx('h2', { className: 'text-sm font-medium', key: 'h', children: 'Hermes Composer Spellcheck' }),
      jsx('span', {
        className: 'text-xs text-(--ui-text-tertiary)',
        key: 'c', children:
        `${total} word${total === 1 ? '' : 's'} · ${locales.length ? locales.join(', ') : locale}` })] }
    ),

    // --- one field: search AND add -------------------------------------
    // A single box. Typing filters the list live; pressing Enter (or the
    // Add button) adds what you typed as a new word. Two separate bars meant
    // you could not see a word you had just added without changing pages.
    jsx('div', { className: 'flex items-center gap-2', key: 'add', children: [
      jsx(SearchField, {
        key: 's',
        // SearchField sizes itself to its text (`field-sizing: content`), so
        // it must be told to stretch or the merged field comes out narrower
        // than the search bar and the add bar it replaced. Tailwind only
        // generates the arbitrary values the app itself uses, so the override
        // goes straight on the DOM node via the ref the component exposes.
        containerClassName: 'w-full flex-1',
        inputRef: (node) => {
          if (node) {
            node.style.fieldSizing = 'fixed';
          }
        },
        onChange: (value) => {
          setQuery(value);
          setDraft(value);
        },
        onKeyDown: (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            commit();
          }
        },
        placeholder: total
          ? `Search or add — ${total} word${total === 1 ? '' : 's'}`
          : 'Search or add a word',
        value: query
      }),
      jsx(Button, {
        disabled: !draft.trim(),
        key: 'b',
        onClick: commit,
        variant: 'secondary',
        children: 'Add'
      })] }
    ),

    // --- list -----------------------------------------------------------
    jsx('div', { className: 'min-h-24 flex-1 overflow-y-auto', key: 'list', children:
      shown.length === 0 ?
      jsx(EmptyState, {
        description:
        total === 0 ?
        'Right-click an underlined word in the composer and choose “Add to dictionary”, or type one above.' :
        `Nothing matches “${query.trim()}”.`,
        key: total === 0 ? 'empty' : 'nf',
        title: total === 0 ? 'No custom words yet' : 'No matches'
      })
      // Plain rows rather than ListRow: ListRow's label/control split is
      // driven by a container query on --conversation-text-font-size, and
      // those theme vars are not in scope outside the settings pane, so the
      // row rendered with no measurable size — the page showed its count
      // and search box but an empty-looking list. These styles stand alone.
      : jsx('div', { className: 'flex flex-col', key: 'rows', children:
        shown.map((entry) =>
        jsx('div', {
          className: 'flex items-center justify-between gap-2 py-1',
          key: `${entry.locale}:${entry.word}`, children:
          [
          jsx('span', {
            className: 'min-w-0 flex-1 truncate text-sm text-(--ui-text-primary)',
            key: 'w', children:
            entry.word }),
          // Only worth the pixels when the list really mixes dictionaries.
          locales.length > 1 ?
          jsx('span', {
            className: 'shrink-0 text-xs text-(--ui-text-tertiary)',
            key: 'l', children:
            entry.locale }) :
          null,
          jsx('button', {
            'aria-label': `Remove ${entry.word}`,
            className:
            'inline-flex h-5 w-5 shrink-0 items-center justify-center rounded cursor-pointer text-(--ui-text-tertiary) hover:bg-(--ui-control-hover-background)',
            key: 'x',
            onClick: () => remove(entry.word, entry.locale),
            type: 'button', children:
            jsx(Codicon, { key: 'i', name: 'trash' }) })] }
        )
        ) }
      ) }
    ),

    // --- footer: what the base dictionary holds ------------------------
    jsx('p', {
      className: 'text-xs text-(--ui-text-tertiary)',
      key: 'foot', children:
      dict.ready ?
      `${dict.words.size.toLocaleString()} words in the built-in dictionary${dict.words.has(locale) ? '' : ''} · custom words are always accepted.` :
      'Loading the built-in dictionary…' })]

  });
}

// ---------------------------------------------------------------------------
// Plugin
// ---------------------------------------------------------------------------

export default {
  id: ID,
  name: 'Hermes Composer Spellcheck',
  // Registers on load: the plugin exists to restore spell check in the
  // composer, so it is on unless the user turns it off in Capabilities.
  defaultEnabled: true,

  register(ctx) {
    const prefs = atom({ ...DEFAULTS, ...(ctx.storage.get('prefs', {}) || {}) });

    // Custom words survive a reload now. This list is the plugin's source of
    // truth (it drives the Custom Words page and our own recognition); the
    // app's spell-check dictionary is a separate store that only paints the
    // underline.
    //
    // The old startup REPLAY is gone with the bridge that needed it: that
    // existed because a word could be saved to our list while
    // `contextMenuSpellcheck` was unavailable, so it had to be re-pushed into
    // Chromium on every load. The app's dictionary is persistent — a word
    // added through `host.spellcheck.addWord` is already remembered by the
    // app on the next launch, so pushing it again would only duplicate work.
    loadAllowed(ctx.storage);

    const P = (...a) => console.error('[spellcheck]', ...a);

    /**
     * Load the active locale once, up front, so the first right-click is not
     * the thing that pays for a multi-megabyte download.
     */
    let ready = null;

    function ensureReady() {
      if (!ready) {
        const locale = activeLocale(prefs.get());

        ready = ensureLocale(prefs.get()).
        then((entry) => {
          P('dictionary ready:', locale, 'words=' + entry.words.size);
          return entry;
        }).
        catch((err) => {
          P('dictionary FAILED:', locale, err.message);
          // Clear so a language switch can retry.
          ready = null;
          return rankFor('en');
        });
      }

      return ready;
    }

    void ensureReady();

    // The suggestion rows are a CONTRIBUTION, not an injection: the app asks
    // every plugin for its rows when it opens the composer's context menu,
    // renders them as their own section of its own menu, and calls onSelect
    // after it has closed the menu and returned the caret to the composer. We
    // never query or mutate that menu's DOM.
    //
    // `items` is synchronous by contract, which is why the locale is warmed at
    // register() above: a dictionary that is still loading contributes no rows
    // rather than making the menu wait for a download.
    //
    // The area is FEATURE-DETECTED. An older shell's `COMPOSER_AREAS` has no
    // `contextMenu` key, and registering against `undefined` would either file
    // the contribution into an area nothing resolves or throw — so the menu is
    // skipped, the user is told once, and everything else registers as usual.
    const menuArea = composerMenuArea();

    if (menuArea) {
      ctx.register({
        id: 'spellcheck-suggestions',
        area: menuArea,
        data: {
          items: (menu) => prefs.get().enabled ?
            suggestionItems(menu?.word, activeLocale(prefs.get()), ctx.storage) :
            []
        }
      });
    } else {
      noticeMenuSeamMissing();
    }

    // Code spans are DECLARED, not painted: one `ctx.register` with
    // `area: COMPOSER_AREAS.nonProse` and `data: { ranges }`. The app asks every
    // provider for the non-prose ranges of the draft it is about to render,
    // wraps each one in a span it emits and owns, and keeps that span across
    // its own reconciler passes. The plugin never sees a node — not the
    // composer's, not the wrapper's.
    //
    // The seam is FEATURE-DETECTED exactly like the menu's: a shell without
    // `COMPOSER_AREAS.nonProse` gets no registration, no throw and no notice,
    // and the composer underlines code like any other text.
    //
    // The SETTING gates the ranges, not the registration. There is no
    // unregister-on-toggle path to get wrong, and an empty range list from a
    // registered provider is precisely "nothing here is code" — which is what
    // the app asks for on a draft with none. A flip takes effect the next time
    // the app rebuilds the composer's content (the provider is consulted on
    // every render), so no listener is needed to push it.
    const nonProseArea = composerNonProseArea();

    if (nonProseArea) {
      ctx.register({
        id: 'code-spans',
        area: nonProseArea,
        data: {
          ranges: ({ text } = {}) => prefs.get().excludeCodeSpans ?
            codeSpanRanges(text) :
            []
        }
      });
    }

    // Re-assert on focus rather than observing document.body (watching app DOM
    // is a forbidden plugin construct): the host applies setSpellcheck to the
    // composer that exists when it is called, and focus is the one signal the
    // plugin already gets when a composer comes into use.
    const onFocusIn = () => applySpellcheck(prefs.get().enabled);

    ctx.addEventListener(document, 'focusin', onFocusIn, true);

    applySpellcheck(prefs.get().enabled);

    ctx.onDispose(() => {
      // The ctx-scoped listeners above are removed by the host with the
      // plugin; this only has to undo what we did to the composer. The
      // contribution and the route go with the registry.
      applySpellcheck(false);
    });

    // Dictionary page: full-pane view + a sidebar tab, mirroring how the
    // quota plugin exposes /quota.
    ctx.register({
      id: 'dictionary-page',
      area: ROUTES_AREA,
      data: { path: '/spellcheck-dictionary' },
      render: () => jsx(DictionaryPage, { prefs, storage: ctx.storage })
    });

    // The sidebar row is OPTIONAL. The Custom Words page is always reachable
    // from Settings -> Plugins, so hiding the row never hides the feature.
    //
    // The row is registered and unregistered as the toggle flips, rather than
    // gated on a `when()` predicate: the contribution registry CACHES the
    // resolved list for an area and only invalidates it on a registry
    // mutation, so a pref-driven `when()` would not re-resolve when the user
    // flips the switch.
    let removeNavRow = null;

    const syncNavRow = () => {
      const wanted = prefs.get().showSidebarTab !== false;

      if (wanted && !removeNavRow) {
        removeNavRow = ctx.register({
          id: 'dictionary-nav',
          area: SIDEBAR_NAV_AREA,
          order: 90,
          data: {
            codicon: 'book',
            label: 'Spellcheck',
            path: '/spellcheck-dictionary'
          }
        });
      } else if (!wanted && removeNavRow) {
        removeNavRow();
        removeNavRow = null;
      }
    };

    syncNavRow();

    // Deep-link the Custom Words SUB-PAGE from inside the plugin's own
    // settings page. The rail already lists it under this plugin, so the
    // target is the same route the rail navigates to: Settings stays open and
    // the content pane swaps to the word list, instead of the whole overlay
    // closing on a route change.
    //
    // ID is this module's own exported id — the same string the host registers
    // the page under, and the same one the settings rail links to.
    const openCustomWords = () => {
      host.navigate(pluginSettingsHref(ID, 'words'));
    };

    ctx.registerSettingsPage?.({
      id: 'settings',
      title: 'Composer Spell Check',
      icon: 'check',
      // The custom-words browser lives in the SAME home as the rest of the
      // plugin's preferences — Settings -> Plugins is "the one home for
      // plugin preferences" (Desktop Plugin SDK docs). The sidebar row and
      // the /spellcheck-dictionary route stay as a second way in, because
      // the word list is a page of its own, not a preference row.
      children: [
        {
          id: 'words',
          title: 'Custom Words',
          render: () => jsx(DictionaryPage, { prefs, storage: ctx.storage })
        }
      ],
      render: () => {
        function Page() {
          const p = useValue(prefs);

          const set = (patch) => {
            const next = { ...p, ...patch };

            prefs.set(next);
            ctx.storage.set('prefs', next);
            applySpellcheck(next.enabled);

            // A language change re-fetches for the new locale.
            if (patch.language && patch.language !== p.language) {
              ready = null;
              void ensureReady();
            }

            // The sidebar row follows the toggle. The registry caches the
            // resolved area list, so the row is re-registered rather than
            // gated on a when() predicate.
            if (patch.showSidebarTab !== undefined) {
              syncNavRow();
            }
          };

          // Every value here is a locale the plugin can actually load: 'en' is
          // embedded, and the rest have an index.dic/index.aff at the pinned
          // upstream commit. The three regional English dictionaries are in
          // the list because LOCALE_MAP resolves them and loadDictionary()
          // fetches them exactly like any other locale — leaving them out
          // made them reachable only by hand-editing the pref.
          const locales = ['auto', 'en', 'en-GB', 'en-AU', 'en-CA', 'de', 'fr', 'es',
          'it', 'pt', 'nl', 'pl', 'ru', 'uk', 'sv', 'tr', 'cs', 'da', 'el', 'he', 'fa',
          'ko'];

          return jsxs('div', { className: 'flex flex-col gap-1', children: [
            jsx(ToggleRow, {
              checked: p.enabled,
              description:
              'Underlines misspellings with the standard SCOWL/Hunspell dictionary and offers right-click suggestions. Turning it off stops both.',
              key: 'on',
              label: 'Check spelling',
              onChange: (value) => set({ enabled: value })
            }),
            jsx(ListRow, {
              description: 'Dictionary used for suggestions. Automatic follows the app locale.',
              key: 'lang',
              title: 'Language'
            }),
            jsx('select', {
              className: 'mx-3 mb-2 rounded-md border px-2 py-1',
              key: 'sel',
              onChange: (e) => set({ language: e.target.value }),
              value: p.language,
              children: locales.map((l) =>
              jsx('option', { key: l, value: l, children: l === 'auto' ? 'Automatic' : l })
              )
            }),
            // Offered only when the shell carries the `composer.nonProse` seam.
            // A switch that cannot do anything is worse than an absent one, and
            // the stored preference is left untouched, so the option is back —
            // still set to whatever the user chose — on a build that can honour
            // it. Same feature detection as the provider registration.
            nonProseArea ? jsx(ListRow, {
              action: jsx(Switch, {
                checked: p.excludeCodeSpans,
                key: 'sw',
                label: '',
                onCheckedChange: (value) => set({ excludeCodeSpans: value })
              }),
              description: 'Do not underline `backtick` code spans, file names or paths.',
              key: 'code',
              title: 'Ignore code spans'
            }) : null,
            jsx(ListRow, {
              action: jsx(Switch, {
                checked: p.showSidebarTab !== false,
                key: 'nav',
                label: '',
                onCheckedChange: (value) => set({ showSidebarTab: value })
              }),
              description:
              'Show a Spellcheck row in the sidebar. The Custom Words page is always available from this page, whether the row is shown or not.',
              key: 'navrow',
              title: 'Show in the sidebar'
            }),
            // The word list is a page of its own, and it is reachable from
            // HERE without leaving Settings: this row deep-links the sub-page
            // the rail already lists, so the pane swaps in place instead of
            // the whole Settings overlay closing.
            //
            // The WHOLE row is the button — the app's own settings nav rows
            // are one click target, title and chevron together, with no
            // second "open" link to discover.
            jsx('button', {
              className: 'flex w-full min-h-11 cursor-pointer items-center gap-3 rounded-md border border-(--ui-stroke-tertiary) px-3 py-3 text-left transition-colors hover:bg-(--chrome-action-hover)',
              key: 'open',
              onClick: openCustomWords,
              type: 'button',
              children: [
                jsx('span', {
                  className: 'min-w-0 flex-1',
                  key: 'text',
                  children: [
                    jsx('span', {
                      className: 'block truncate text-[length:var(--conversation-text-font-size)] font-medium text-foreground',
                      key: 'title',
                      children: 'Custom Words'
                    }),
                    jsx('span', {
                      className: 'mt-1 block text-[length:var(--conversation-caption-font-size)] text-(--ui-text-tertiary)',
                      key: 'desc',
                      children: 'Search, add and remove the words the spell checker always accepts.'
                    })
                  ]
                }),
                jsx(Codicon, {
                  className: 'shrink-0 text-(--ui-text-tertiary)',
                  key: 'chevron',
                  name: 'chevron-right',
                  size: '0.8rem'
                })
              ]
            })] }
          );
        }

        return jsx(Page, {});
      }
    });
  }
};
